import os
import shutil

def create_directory(path):
    """Create a directory if it doesn't exist."""
    try:
        if not os.path.exists(path):
            os.makedirs(path)
            print(f"Directory '{path}' created.")
        else:
            print(f"Directory '{path}' already exists.")
    except Exception as e:
        print(f"Error creating directory '{path}': {e}")

def move_files(src, dst):
    """Move all files from src to dst."""
    try:
        if not os.path.exists(src):
            print(f"Source directory '{src}' does not exist.")
            return

        if not os.path.exists(dst):
            os.makedirs(dst)

        for item in os.listdir(src):
            s = os.path.join(src, item)
            d = os.path.join(dst, item)
            if os.path.isdir(s):
                shutil.move(s, d)
            else:
                shutil.move(s, d)
            print(f"Moved '{s}' to '{d}'")

    except Exception as e:
        print(f"Error moving files from '{src}' to '{dst}': {e}")

def update_file_content(file_path, old_string, new_string):
    """Update the content of a file by replacing old_string with new_string."""
    try:
        if not os.path.exists(file_path):
            print(f"File '{file_path}' does not exist.")
            return

        with open(file_path, 'r') as file:
            file_contents = file.read()

        file_contents = file_contents.replace(old_string, new_string)

        with open(file_path, 'w') as file:
            file.write(file_contents)
            print(f"Updated '{file_path}' with new content.")

    except Exception as e:
        print(f"Error updating file '{file_path}': {e}")

def delete_directory(path):
    """Delete a directory if it is empty."""
    try:
        if os.path.exists(path):
            if not os.listdir(path):
                os.rmdir(path)
                print(f"Directory '{path}' deleted.")
            else:
                shutil.rmtree(path)
                print(f"Directory '{path}' deleted (non-empty).")
        else:
            print(f"Directory '{path}' does not exist.")
    except Exception as e:
        print(f"Error deleting directory '{path}': {e}")

def main():
    src_dir = "_internal_utils"
    dst_dir = "utils"

    # Step 1: Create the utils directory
    create_directory(dst_dir)

    # Step 2: Move all files from _internal_utils to utils
    move_files(src_dir, dst_dir)

    # Step 3: Update all references in the codebase
    files_to_update = [
