def recursive_diff(d1, d2, log=False):
    """
    Recursively compare two dictionaries and log differences if log is True.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        if d1 != d2 and log:
            print(f"Difference found: {d1} != {d2}")
        return d1 != d2

    diff = {}
    for key in d1.keys() | d2.keys():
        if key in d1 and key in d2:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                sub_diff = recursive_diff(d1[key], d2[key], log=log)
                if sub_diff:
                    diff[key] = sub_diff
            elif d1[key] != d2[key]:
                if log:
                    print(f"Difference found at key '{key}': {d1[key]} != {d2[key]}")
                diff[key] = (d1[key], d2[key])
        elif key in d1:
            if log:
                print(f"Key '{key}' missing in second dictionary: {d1[key]}")
            diff[key] = (d1[key], None)
        elif key in d2:
            if log:
                print(f"Key '{key}' missing in first dictionary: {d2[key]}")
            diff[key] = (None, d2[key])

    return diff
