import logging

logger = logging.getLogger(__name__)

def xmliter(obj, nodename=None, log=True):
    """
    Iterates over XML elements in a given object.

    :param obj: The object to iterate over (can be a dictionary or list).
    :param nodename: The name of the XML node to look for (must be a string).
    :param log: Boolean flag to enable or disable logging. Default is True.
    :yield: Values corresponding to the specified nodename.
    """
    if nodename is not None and not isinstance(nodename, str):
        raise ValueError("nodename must be a string")

    if log:
        logger.debug(f"Processing node: {nodename}")

    if isinstance(obj, dict):
        for key, value in obj.items():
            if key == nodename:
                yield value
            elif isinstance(value, (dict, list)):
                yield from xmliter(value, nodename, log=log)
    elif isinstance(obj, list):
        for item in obj:
            yield from xmliter(item, nodename, log=log)
    else:
        raise TypeError("obj must be a dictionary or list")

