# Configure logging for tests
logging.basicConfig(level=logging.DEBUG)

class TestXmliter(unittest.TestCase):

    def test_xmliter_no_log(self):
        data = {
            'root': {
                'child': {
                    'subchild': 'value'
                }
            }
        }
        result = list(xmliter(data, 'subchild', log=False))
        self.assertEqual(result, ['value'])

    def test_xmliter_with_log(self):
        data = {
            'root': {
                'child': {
                    'subchild': 'value'
                }
            }
        }
        result = list(xmliter(data, 'subchild', log=True))
        self.assertEqual(result, ['value'])

    def test_xmliter_nested(self):
        data = {
            'root': [
                {'child': {'subchild': 'value1'}},
                {'child': {'subchild': 'value2'}}
            ]
        }
        result = list(xmliter(data, 'subchild', log=False))
        self.assertEqual(result, ['value1', 'value2'])

    def test_xmliter_empty_dict(self):
        data = {}
        result = list(xmliter(data, 'subchild', log=False))
        self.assertEqual(result, [])

    def test_xmliter_empty_list(self):
        data = []
        result = list(xmliter(data, 'subchild', log=False))
        self.assertEqual(result, [])

    def test_xmliter_no_matching_nodename(self):
        data = {
            'root': {
                'child': {
                    'other': 'value'
                }
            }
        }
        result = list(xmliter(data, 'subchild', log=False))
        self.assertEqual(result, [])

    def test_xmliter_invalid_nodename(self):
        data = {
            'root': {
                'child': {
                    'subchild': 'value'
                }
            }
        }
        with self.assertRaises(ValueError):
            list(xmliter(data, 123, log=False))

    def test_xmliter_invalid_obj(self):
        data = "invalid"
        with self.assertRaises(TypeError):
            list(xmliter(data, 'subchild', log=False))

if __name__ == '__main__':
    unittest.main()
